        public static double CardP(Card c, Suit? trump, int roundSize, int myTrumpLen)
        {
            int s = Math.Clamp(roundSize, 1, 13);
            if (trump.HasValue && c.Suit == trump.Value)
                return PT[(int)c.Rank, s, Math.Clamp(myTrumpLen, 1, 4)];
            return PS[(int)c.Rank, s];
        }

        public static double ExpectedTricks(IReadOnlyList<Card> hand, Suit? trump, int roundSize)
        {
            int tl = trump.HasValue ? hand.Count(c => c.Suit == trump.Value) : 0;
            double sum = 0;
            foreach (var c in hand) sum += CardP(c, trump, roundSize, tl);
            return Math.Min(sum, hand.Count);
        }
    }
